@startuml

abstract class Person {
  +firstName : string
  +lastName : string
}

class Teacher extends Person {
  +emailAddress : string
}

class Student extends Person {}

class School {
  +name : string
}

class TeachingRelationship {
  +hours : int
}

class Room {}

class ClassRoom extends Room {
  +name : string
  +capacity : int
}

class OtherRoom extends Room {
  +name : string
  +size : float
}

class ClassGroup {
  +name : string
}

School "1" -- "*" Teacher : employs
School "1" -- "0..3" Teacher : teacher works at
School "1" -- "1" Teacher : principal
School "1" *-- "*" Room
School "1" -- "1" Student : attends
ClassGroup "1" -- "10..31" Student : contains
ClassGroup "1" -- "1" ClassRoom : assigned to
ClassRoom "1" -- "1" ClassGroup : assigned to

Teacher "1" -- "*" TeachingRelationship
TeachingRelationship "*" -- "1" School

@enduml

